func testFrenteCaixaToManyRemoveOpFRTCXLancamentoFinanceiros(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a FrenteCaixa
	var b, c, d, e LancamentoFinanceiro

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, frenteCaixaDBTypes, false, strmangle.SetComplement(frenteCaixaPrimaryKeyColumns, frenteCaixaColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*LancamentoFinanceiro{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, lancamentoFinanceiroDBTypes, false, strmangle.SetComplement(lancamentoFinanceiroPrimaryKeyColumns, lancamentoFinanceiroColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddFRTCXLancamentoFinanceiros(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.FRTCXLancamentoFinanceiros().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveFRTCXLancamentoFinanceiros(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.FRTCXLancamentoFinanceiros().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.FRTCXID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.FRTCXID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.FRTCX != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.FRTCX != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.FRTCX != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.FRTCX != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.FRTCXLancamentoFinanceiros) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.FRTCXLancamentoFinanceiros[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.FRTCXLancamentoFinanceiros[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

